//! Frozen-ViT demo: the plan is generated by `build.rs`, included here, and
//! executed without any runtime scheduling or `rustc`.

include!(concat!(env!("OUT_DIR"), "/frozen.rs"));
include!("make_vit.rs");

use autorust::engine::session::Session;
use autorust::freeze::{Engine, Frozen};

fn main() {
    let ctx = Ctx::new();
    let mut sess = Session::new();
    let (model, weights, x) = make(&ctx);

    // Reference through the normal eager path (same deterministic weights).
    let eager = model.forward(&x).to_list::<f32>(&mut sess);

    let frozen = Frozen::<autorust::models::vit::ViT>::new(plan(), KERNELS.to_vec(), weights);
    let mut engine = Engine::new(model, frozen);
    let got = engine.forward(x).to_list::<f32>(&mut sess);

    assert_eq!(got, eager, "frozen ViT differs from eager");
    println!(
        "frozen ViT: {} logits, matches eager (eager path selected: {})",
        got.len(),
        engine.is_eager()
    );
}
